head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _4 : inputType 별로 전달 여부가 갈리는 파라미터 전용 분리 샘플.
//     oldSelectedIndex / newSelectedIndex / oldInfo / newInfo 4개 파라미터와
//     각각의 "~ 인 경우에만 포함됩니다" 하위절을 검증한다.
//     Body Column 을 text / select(가이드 표기 selectbox) / autoComplete / checkcombobox 4종으로 구성하여
//     같은 이벤트에서 inputType 에 따라 어떤 파라미터가 포함/미포함 되는지 대비한다.
//     기본 구성(info/rowIndex/colIndex/oldValue/newValue/colId/@spec) 은 _1,
//     MultiLine 은 _2, DrillDown 은 _3 샘플에서 다루므로 본 샘플에서는 제외.
scwin.tData = {
    "description" : "[gridView > E > onviewchange]<br/>사용자의 조작에 의해 Body Cell 의 데이터가 변경된 후 포커스가 해제될때 발생합니다.",
    "validation" : [
        "oldSelectedIndex 파라미터는 Body Cell 의 변경 전 선택 인덱스값을 갖습니다.",
        "oldSelectedIndex 파라미터는 inputType='selectbox','autoComplete','checkcombobox' 인 경우에만 포함됩니다.",
        "newSelectedIndex 파라미터는 Body Cell 의 변경 후 선택 인덱스값을 갖습니다.",
        "newSelectedIndex 파라미터는 inputType='selectbox','autoComplete','checkcombobox' 인 경우에만 포함됩니다.",
        "oldInfo 파라미터는 Body Cell 의 변경 전 체크 항목을 배열로 갖습니다.",
        "oldInfo 파라미터는 inputType='checkcombobox' 인 경우에만 포함되며 배열의 각 요소는 {index, label, value, checked} 구조의 객체입니다.",
        "newInfo 파라미터는 Body Cell 의 변경 후 체크 항목을 배열로 갖습니다.",
        "newInfo 파라미터는 inputType='checkcombobox' 인 경우에만 포함되며 배열의 각 요소는 {index, label, value, checked} 구조의 객체입니다."
    ]
}



// Body Column id -> inputType 표기 (결과창에서 어떤 inputType 의 Cell 인지 구분)
scwin.INPUT_TYPE = {
    "txt"  : "text",
    "sel"  : "select(=selectbox)",
    "auto" : "autoComplete",
    "chk"  : "checkcombobox"
};

// 검증 대상 파라미터 (inputType 에 따라 포함/미포함이 갈리는 4개)
scwin.KEYS = ["oldSelectedIndex", "newSelectedIndex", "oldInfo", "newInfo"];



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 아이템 DataList 원본 (select / autoComplete / checkcombobox 공용)
scwin.ITEM_DATA = [
    { "code": "A", "label": "서울" },
    { "code": "B", "label": "부산" },
    { "code": "C", "label": "대구" },
    { "code": "D", "label": "광주" }
];

// 그리드 바인딩 데이터 (chk 는 checkcombobox 다중값 -> 공백 구분 코드값)
scwin.BIND_DATA = [
    { "txt": "노트북", "sel": "A", "auto": "A", "chk": "A" },
    { "txt": "모니터", "sel": "B", "auto": "B", "chk": "A B" },
    { "txt": "키보드", "sel": "C", "auto": "C", "chk": "C" }
];



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - Body Column 4종 : 0 txt(text) / 1 sel(select) / 2 auto(autoComplete) / 3 chk(checkcombobox)
//  - 사용자가 Cell 을 편집해 값을 바꿔야 이벤트가 발생하므로 editable="true" 로 생성한다.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_item !== 'undefined' && dlt_item) {
        $p.data.remove(dlt_item.id);
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  · createLabel 문자 제약 : 작은따옴표 금지, 줄바꿈은 개행 이스케이프만 사용
    $c.gcm.createLabel('label="[전제] Body Column 4종 - 0:txt(text) / 1:sel(select, 가이드 표기 selectbox) / 2:auto(autoComplete) / 3:chk(checkcombobox). 아이템은 서울/부산/대구/광주 4개로 동일하며 모두 편집 가능합니다.\n[절차] txt = 더블클릭해 글자를 바꾼 뒤 다른 Cell 클릭\n[절차] sel = 더블클릭해 목록을 열고 다른 항목 선택\n[절차] auto = 더블클릭해 목록을 열고 다른 항목 선택\n[절차] chk = 더블클릭해 목록을 열고 항목 여러 개를 체크/해제한 뒤, 오른쪽 콤보 버튼을 다시 클릭해 목록을 닫기 (다른 Cell 을 클릭해 닫으면 체크 항목 배열 없이 이벤트만 발생하므로 반드시 콤보 버튼으로 닫을 것)\n[확인] 결과창의 oldSelectedIndex / newSelectedIndex / oldInfo / newInfo 4줄이 값으로 나오는지 (전달되지 않음 - 키 자체가 없음) 으로 나오는지 inputType 별로 비교\n[참고] Cell 편집 중에는 [Target 재생성] 을 누르지 말고, 다른 Cell 을 클릭해 편집을 빠져나온 뒤 눌러 주세요."', '', 'label1');

    // 아이템용 DataList (select / autoComplete / checkcombobox 공용) - value=code, label=label
    let strItem = '';
    strItem += '<w2:dataList ' + strNameSpace + ' id="dlt_item" baseNode="list" repeatNode="map">';
    strItem += '<w2:columnInfo>';
    strItem += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strItem += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strItem += '</w2:columnInfo>';
    strItem += '<w2:data use="true"></w2:data>';
    strItem += '</w2:dataList>';
    $p.data.create(strItem);
    dlt_item.setJSON(scwin.ITEM_DATA, false);

    // GridView 와 바인딩할 DataList 동적 생성
    //  ★ DataList 컬럼 id 와 gBody 컬럼 id/dataList 를 모두 동일하게 (불일치 시 셀 빈값)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="txt" name="txt" dataType="text"></w2:column>';
    strDlt += '<w2:column id="sel" name="sel" dataType="text"></w2:column>';
    strDlt += '<w2:column id="auto" name="auto" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.BIND_DATA, false);

    // itemset 공통 조각 (select / autoComplete / checkcombobox 용) : value ref=code, label ref=label
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_item"><w2:label ref="label"></w2:label><w2:value ref="code"></w2:value></w2:itemset></w2:choices>';

    // target 그리드 직접 구성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" editable="true" checkAllType="false" defaultCellHeight="30" ev:onviewchange="scwin.target1_onviewchange" id="" style="width:100%;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="onviewchange inputType sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="110" style="" inputType="text" id="h0" value="txt(text)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="h1" value="sel(selectbox)"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="h2" value="auto(autoComplete)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="h3" value="chk(checkcombobox)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    // 0 txt (text) -> selectedIndex / Info 미포함 대비용
    strTarget += '<w2:column width="110" style="" inputType="text" id="txt" dataList="txt"></w2:column>';
    // 1 sel (select = 가이드 표기 selectbox)
    strTarget += '<w2:column width="120" style="" inputType="select" id="sel" dataList="sel">' + itemset + '</w2:column>';
    // 2 auto (autoComplete)
    strTarget += '<w2:column width="130" style="" inputType="autoComplete" id="auto" dataList="auto">' + itemset + '</w2:column>';
    // 3 chk (checkcombobox) -> oldInfo / newInfo 포함 검증용
    strTarget += '<w2:column width="*" style="" inputType="checkcombobox" id="chk" dataList="chk">' + itemset + '</w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 파라미터 포함 여부/값 표기
//  · 키 자체가 없는 경우와 키는 있으나 값이 undefined 인 경우를 구분해서 표기한다.
//  · 배열(oldInfo/newInfo) 은 각 요소의 {index, label, value, checked} 구조까지 펼쳐서 표기한다.
scwin.fmtParam = function (info, key) {
    if (!(key in info)) {
        return "(전달되지 않음 - 키 자체가 없음)";
    }
    let value = info[key];
    if (typeof value === "undefined") {
        return "(전달됨 - 키는 있으나 값은 undefined)";
    }
    if (Object.prototype.toString.call(value) === "[object Array]") {
        let arr = [];
        for (let i = 0; i < value.length; i++) {
            let item = value[i];
            arr.push("{index:" + item.index + ", label:" + item.label + ", value:" + item.value + ", checked:" + item.checked + "}");
        }
        return "[" + arr.join(", ") + "]";
    }
    return value;
}



// onviewchange : 사용자의 조작으로 Body Cell 의 데이터가 변경된 후 포커스가 해제될때 발생.
//  ▶ inputType 별 파라미터 포함 여부 검증에 필요한 4개 파라미터만 출력
scwin.target1_onviewchange = function (info) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("▶ onviewchange [inputType : " + scwin.INPUT_TYPE[info.colId] + "]");
    for (let i = 0; i < scwin.KEYS.length; i++) {
        bottom.setReturnValue("info." + scwin.KEYS[i] + " : " + scwin.fmtParam(info, scwin.KEYS[i]));
    }
}
